'use client'

import { useId } from 'react'
import { Input, Label } from '@timui/react'

import { useCharacterLimit } from '@/registry/default/hooks/use-character-limit'

export default function Component() {
  const id = useId()
  const maxLength = 8
  const { value, characterCount, handleChange, maxLength: limit } = useCharacterLimit({ maxLength })

  return (
    <div className="*:not-first:mt-2">
      <Label htmlFor={id}>Input with characters left</Label>
      <Input
        id={id}
        type="text"
        value={value}
        maxLength={maxLength}
        onChange={handleChange}
        aria-describedby={`${id}-description`}
      />
      <p
        id={`${id}-description`}
        className="text-muted-foreground mt-2 text-xs"
        role="status"
        aria-live="polite"
      >
        <span className="tabular-nums">{limit - characterCount}</span> characters left
      </p>
    </div>
  )
}

'use client'

import { ChangeEvent, useState } from 'react'

type UseCharacterLimitProps = {
  maxLength: number
  initialValue?: string
}

export function useCharacterLimit({ maxLength, initialValue = '' }: UseCharacterLimitProps) {
  const [value, setValue] = useState(initialValue)
  const [characterCount, setCharacterCount] = useState(initialValue.length)

  const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const newValue = e.target.value
    if (newValue.length <= maxLength) {
      setValue(newValue)
      setCharacterCount(newValue.length)
    }
  }

  return {
    value,
    characterCount,
    handleChange,
    maxLength,
  }
}
